export interface Gloss {
  pos?: string
  meaning: string
}

export const GLOSSARY: Record<string, Gloss> = Object.fromEntries(
  TSV.trim()
    .split('\n')
    .map((line) => {
      const [word, pos, meaning] = line.split('\t')
      return [word, { pos: pos || undefined, meaning }]
    }),
)
